    "description": "中新网哈尔滨8月15日电(记者 刘璐)8月14日，黑龙江省高级人民法院举行“黑龙江环境资源审判五周年(2021-2025)”新闻发布会。记者从会上获悉，五年来，黑龙江法院积极践行恢复性司法理念，着力推动生态环境损害从“惩治”走向“修复”，初步构建覆盖刑事、民事、行政三大审判领域的生态修复工作体系，以司法力量筑牢祖国北方生态安全屏障。",
    "content": "中新网哈尔滨8月15日电(记者 刘璐)8月14日，黑龙江省高级人民法院举行“黑龙江环境资源审判五周年(2021-2025)”新闻发布会。记者从会上获悉，五年来，黑龙江法院积极践行恢复性司法理念，着力推动生态环境损害从“惩治”走向“修复”，初步构建覆盖刑事、民事、行政三大审判领域的生态修复工作体系，以司法力量筑牢祖国北方生态安全屏障。"
