    "content": "假如有两条 VPN 线路： R1 ===== R3 ===== R4 PRIMARY （成本可接受,低延迟,大宽带,假设 100Mbps ） R1 ----- R2 ----- R4 BACKUP （成本超高按流量计费,更稳定,主要做备份） 我希望能保障 R1-R4 的链路高可用 故障 假如今天： R1 ───────── R3 100M 未来某天： R1 ───────── R3 ↓ 20M ↓ 丢包/延迟暴涨 根据链路质量快速切换 正常 R1 ─────── R3 ────── R4 100M ↓ 质量恶化 R…"
