    "content": "静音鼠标爱好者，办公室里不喜欢鼠标点击咔哒咔哒的声音。 原来一直用的款是罗技 M590 （已停产），gpt 查了一下说后续改款是 M650 ，结果买回来感觉完全不是一个东西。 握持手感类似，好评 按键削减很厉害，原先 M590 是有侧面 2 按键+鼠标中键靠左/靠右拨动，这四个扩展按键的，现在只剩侧键了，中键改成联动逻辑，我很不喜欢。 问下万能的 v 友，不知道还有没有其他平替款，要求是分应用能设置四个扩展按键绑定任意键盘快捷键。 我现在不能鼠标直接点按 ctrl+W / ctrl+T 之类的快捷键的话，感觉浏览器…"
