    "content": "印度尼西亚弗洛勒斯岛附近海域15日清晨发生7.7级地震，已造成2人死亡。根据印尼气象、气候和地球物理局最新通报，地震引发的海啸预警已解除。 通报说，震中位于东努沙登加拉省姆拜镇东北30公里处海域，震源深度15公里。地震发生时，弗洛勒斯岛多个城镇有震感，不少居民在惊慌中冲到马路上避难。 印尼抗灾部门说，地震已造成2人死亡，并警告仍有发生余震的可能。 中国驻登巴萨总领馆当天发布公告提醒领区中国公民，特别是在东努省拉布安巴焦一带的游客，保持高度警惕，密切关注当地地震预警信息以及防灾预警，谨防余震和海啸风险，远离海边。 印…"
