    "content": "快科技8月15日消息，近日海南三亚一家租车行里发生了堪称千钧一发的惊险一幕，整个事件的后续走向让不少网友看完直呼既后怕又暖心。 一辆市场价约六七十万元的保时捷718刚刚在租车行完成还车全流程验车，此前用车的客户下车时没有拉手刹，车辆仅挂在空挡挡位，停在场内的下坡路段没几分钟就开始不受控制地缓慢向后溜行。 让人完全没料到的是，这辆后溜的保时捷身后不足数米的位置，正停着车行名下一辆市值超过七百余万元的劳斯莱斯豪车，要是两车直接相撞，后续的维修定损金额轻轻松松就能达到数百万，光是劳斯莱斯的整车补漆和工时费，都足以抵得上不…"
