    "content": "大家好，最近又折腾了一个新 App ，叫 存息簿 。 功能很简单，就是记录每笔存款的 本金、收益率、起息日、到期日 等信息，并在到期前发送提醒。 主要解决的问题是，家里老人喜欢把钱存定期，还不全在同一家银行。时间一长存款一多，到期日就容易忘。 也很容易搞不清楚： 每个人分别在哪些银行存了多少钱 每笔存款什么时候到期，利息多少 到期之后有没有及时处理 不同银行、不同存款到底哪个收益更高 另外有些银行做活动时，除了利息，还会送积分、礼品或者其他补贴。这些东西其实也有价值，所以存息簿里也可以把这些 额外收益折算进去 ，一…"
