    "content": "新华社德黑兰8月15日电 伊朗副外长卡泽姆·加里布阿巴迪15日回应美国总统特朗普有关霍尔木兹海峡的言论，强调霍尔木兹海峡的开放与关闭都只能由伊朗掌控。 加里布阿巴迪在社交媒体上发文说，特朗普扬言伊朗战败后，他将很快宣布霍尔木兹海峡为美国领土。然而，霍尔木兹海峡并非靠一条推文、一艘航空母舰、一纸命令或一次演说就能被夺取。“霍尔木兹海峡过去是、现在是、将来也是伊朗的。这条海峡的开放与关闭都只能由伊朗掌控。” 加里布阿巴迪强调，伊朗既不畏惧威胁，也不会在武力炫耀面前屈服。美国必须接受现实，到目前为止，美国已遭受战略惨败。…"
