    "content": "新华社东京8月15日电（记者梁晨 李子越）在日本无条件投降81周年之际，日本首相高市早苗15日以“自民党总裁”身份，向供奉有二战甲级战犯的靖国神社供奉“玉串料”（祭祀费）。此外，日本防卫大臣等多名政客分别前往靖国神社参拜。此举引发日本国内爱好和平人士强烈反对。 15日上午，日本防卫大臣小泉进次郎、地方创生担当大臣黄川田仁志、经济安全保障担当大臣小野田纪美和经济财政担当大臣城内实4名现任阁僚先后前往靖国神社参拜。据日本媒体报道，这是继2024年时任防卫大臣木原稔之后，又有现任防卫大臣在8月15日参拜靖国神社；同时也是…"
