    "content": "外交部发言人就日本政要参拜供奉甲级战犯的靖国神社答记者问。 问：8月15日是日本战败投降日。今天日本首相高市早苗向靖国神社供奉祭祀费，还有个别内阁成员参拜靖国神社。中方对此有何评论？ 答： 中方强烈谴责日方涉靖国神社消极动向，已向日方提出严正交涉、强烈抗议。 日本二战时期发动对外侵略战争，犯下惨无人道罪行。所谓“靖国神社”是日本军国主义的精神工具和象征，其供奉的14名甲级战犯是发动侵略战争的罪魁祸首，是事实上的“战犯神社”。无论日本政客编造何种理由，都无法隐藏其为战犯翻案、掩盖战争罪责、歪曲历史事实，为加速“再军事…"
