    "content": "新华社北京8月15日电（记者樊曦）记者15日从中国国家铁路集团有限公司获悉，今年以来，铁路部门积极适应旅客多样化出行需求，精心组织旅客运输，1至7月，全国铁路发送旅客28亿人次、同比增长4.1%，再创历史同期新高。 前7月，铁路部门统筹用好武汉至西安高铁西安东至十堰东段、金华至建德高铁兰溪东至建德段等新线新站资源，加大运力投放，全国铁路日均安排开行旅客列车11462列，同比增加571列、增长5.2%。 跨境旅客运输方面，广深港高铁发送跨境旅客2004.9万人次，中老铁路发送跨境旅客21.4万人次，同比分别增长11.…"
